let persistent=true,saveQueue=Promise.resolve();
DB={v:2,plans:{},snaps:{},notes:[],visits:[],published:1};
function persist({plans=[],snaps=[],notes=[],visits=[]}={}){for(const p of plans)DB.plans[p.id]=p;for(const s of snaps)DB.snaps[s.key]=s;for(const n of notes){const i=DB.notes.findIndex(x=>x.id===n.id);if(i>=0)DB.notes[i]=n;else DB.notes.push(n);SIGD.request('/notifications/read','POST',{id:n.id}).catch(()=>{})}for(const v of visits){if(!DB.visits.some(x=>x.key===v.key))DB.visits.push(v);SIGD.visits=SIGD.visits.then(()=>SIGD.request('/documents/'+v.planId+'/visit','POST',{version:v.version,section:v.sectionId}));SIGD.visits.catch(()=>{})}store.write(DB)}
