 table:(headers,rows)=>`<div class="tw"><table><thead><tr>${headers.map(h=>`<th>${UI.esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Sin registros.</td></tr>`}</tbody></table></div>`,
 mount(el,css){const root=el.attachShadow({mode:'open'});root.innerHTML=`<style>${ICONS}${css}</style><div id="view"></div><div id="message" role="status" aria-live="polite"></div>`;return root},
 field(f,v,id=''){const esc=UI.esc,at=`data-field="${esc(f.id)}" ${id?`data-row="${esc(id)}"`:''} ${f.required?'required':''}`;let control;if(f.type==='boolean')control=`<input type="checkbox" ${at} ${v?'checked':''}>`;else if(f.type==='textarea')control=`<textarea ${at} rows="3">${esc(v)}</textarea>`;else if(f.type==='select')control=`<select ${at}><option value="">Selecciona</option>${(f.options||[]).map(o=>`<option value="${esc(o.value)}" ${v===o.value?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;else control=`<input ${at} type="${f.type==='date'?'date':f.type==='url'?'url':['integer','decimal'].includes(f.type)?'number':'text'}" value="${esc(v)}" ${f.minimum!==undefined?`min="${f.minimum}"`:''} ${f.maximum!==undefined?`max="${f.maximum}"`:''} ${f.maxLength?`maxlength="${f.maxLength}"`:''} step="${f.type==='integer'?'1':'any'}">`;return `<label class="fl field">${esc(f.label)}${f.required?' *':''}${control}</label>`},
 read(root,fields,rowId){const row={id:rowId};for(const f of fields){const el=[...root.querySelectorAll('[data-field]')].find(e=>e.dataset.field===f.id&&(!rowId||e.dataset.row===rowId));if(!el)continue;row[f.id]=f.type==='boolean'?el.checked:['integer','decimal'].includes(f.type)?el.value===''?null:Number(el.value):el.value}return row},
 error(root,e){root.getElementById('message').textContent=e.message},
