function docsFiltrados(){return baseDocentes.filter(d=>(!F.campus||d.campus===F.campus)&&(!F.carrera||d.carrera===F.carrera)&&(!F.semestre||d.semestre===F.semestre)&&(!F.semaforo||d.estado===F.semaforo))}
